def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for color in set(v for row in grid for v in row) - {bg}:
        seen=set()
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=color or (r,c) in seen: continue
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                            seen.add((yy,xx)); stack.append((yy,xx))
                r0=min(y for y,x in cells); r1=max(y for y,x in cells)
                c0=min(x for y,x in cells); c1=max(x for y,x in cells)
                perimeter=({(r0,x) for x in range(c0,c1+1)}|{(r1,x) for x in range(c0,c1+1)}|
                           {(y,c0) for y in range(r0,r1+1)}|{(y,c1) for y in range(r0,r1+1)})
                if r1-r0>=2 and c1-c0>=2 and perimeter.issubset(set(cells)):
                    fill=2 if (r1-r0-1)%2==0 and (c1-c0-1)%2==0 else 7
                    for y in range(r0+1,r1):
                        for x in range(c0+1,c1): out[y][x]=fill
    return out
